```python
#!/usr/bin/env python3
import json
import sys
from collections import Counter
from pathlib import Path

def triage_ndjson(path: Path, threshold: int = 50) -> None:
    denied: Counter[str] = Counter()
    malformed = 0
    with path.open("r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                malformed += 1
                continue
            if rec.get("status") in (401, 403):
                ip = str(rec.get("src_ip", "")).strip()
                if ip:
                    denied[ip] += 1
    for ip, count in denied.most_common():
        if count >= threshold:
            print(f"{ip}\tdenied_401_403={count}")
    print(f"# malformed_lines={malformed}", file=sys.stderr)

if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(f"Usage: {sys.argv[0]} <access.ndjson> [threshold]")
    lim = int(sys.argv[2]) if len(sys.argv) > 2 else 50
    triage_ndjson(Path(sys.argv[1]), lim)
