#!/usr/bin/env python3
import csv
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

def parse_utc(ev: dict) -> datetime:
    if "ts_iso" in ev and ev["ts_iso"]:
        raw = str(ev["ts_iso"]).replace("Z", "+00:00")
        return datetime.fromisoformat(raw).astimezone(timezone.utc)
    if "ts_epoch_ms" in ev and ev["ts_epoch_ms"] is not None:
        return datetime.fromtimestamp(float(ev["ts_epoch_ms"]) / 1000.0, tz=timezone.utc)
    raise ValueError("Missing timestamp field")

def merge_timeline(paths: list[Path]) -> None:
    rows: list[tuple[datetime, str, str, str]] = []
    for p in paths:
        with p.open("r", encoding="utf-8") as f:
            for line in f:
                if not line.strip():
                    continue
                ev = json.loads(line)
                dt = parse_utc(ev)
                rows.append((dt, p.name, str(ev.get("host", "")), str(ev.get("summary", ""))))
    rows.sort(key=lambda r: r[0])
    writer = csv.writer(sys.stdout)
    writer.writerow(["utc_iso", "source_file", "host", "summary"])
    for dt, src, host, summary in rows:
        writer.writerow([dt.strftime("%Y-%m-%dT%H:%M:%S.%fZ"), src, host, summary])

if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(f"Usage: {sys.argv[0]} <events1.jsonl> [events2.jsonl ...]")
    merge_timeline([Path(a) for a in sys.argv[1:]])
```

