#!/usr/bin/env python3
import json
import sys
import uuid
from pathlib import Path

LEVELS = {"low", "medium", "high", "critical"}

def lint_catalog(path: Path) -> list[str]:
    rules = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(rules, list):
        return ["Root element must be a JSON array of rules"]
    errors: list[str] = []
    seen_ids: set[str] = set()
    for idx, r in enumerate(rules):
        rid = str(r.get("id", ""))
        try:
            u = uuid.UUID(rid, version=4)
            if str(u) != rid.lower():
                raise ValueError
        except ValueError:
            errors.append(f"rule[{idx}]: invalid UUIDv4 id '{rid}'")
        if rid in seen_ids:
            errors.append(f"rule[{idx}]: duplicate id '{rid}'")
        seen_ids.add(rid)
        if r.get("level") not in LEVELS:
            errors.append(f"rule[{idx}] ({rid}): invalid level '{r.get('level')}'")
        ls = r.get("logsource")
        if not isinstance(ls, dict) or not (ls.get("category") or ls.get("service")):
            errors.append(f"rule[{idx}] ({rid}): logsource needs category or service")
        cond = (r.get("detection") or {}).get("condition", "")
        if not isinstance(cond, str) or not cond.strip():
            errors.append(f"rule[{idx}] ({rid}): empty detection.condition")
    return errors

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <rules.json>")
    errs = lint_catalog(Path(sys.argv[1]))
    for e in errs:
        print(f"ERROR: {e}")
    sys.exit(1 if errs else 0)
