#!/usr/bin/env python3
import json
import math
import sys
from collections import Counter
from pathlib import Path

def shannon_bpc(s: str) -> float:
    if not s:
        return 0.0
    n = len(s)
    return -sum((c / n) * math.log2(c / n) for c in Counter(s).values())

def hunt_dns(path: Path, min_len: int = 16, min_ent: float = 3.8) -> None:
    seen: set[str] = set()
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            if not line.strip():
                continue
            qname = str(json.loads(line).get("qname", "")).strip(".").lower()
            if not qname or qname in seen:
                continue
            seen.add(qname)
            left = qname.split(".", 1)[0]
            if len(left) >= min_len:
                ent = shannon_bpc(left)
                if ent >= min_ent:
                    print(f"entropy={ent:.3f}\tlen={len(left)}\tqname={qname}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <pdns.ndjson>")
    hunt_dns(Path(sys.argv[1]))
```

