#!/usr/bin/env python3
import email
import email.policy
import re
import sys
from pathlib import Path

URL_RE = re.compile(r"https?://[^\s<>'\")]+", re.IGNORECASE)

def defang(url: str) -> str:
    out = re.sub(r"^http", "hxxp", url, flags=re.IGNORECASE)
    return out.replace(".", "[.]")

def analyze_eml(path: Path) -> None:
    msg = email.message_from_bytes(path.read_bytes(), policy=email.policy.default)
    for hdr in ("From", "Reply-To", "Return-Path", "Subject", "Authentication-Results"):
        print(f"{hdr}: {msg.get(hdr, '<none>')}")
    received = msg.get_all("Received", [])
    print(f"\nReceived hops (bottom-to-top transit = {len(received)}):")
    for idx, hop in enumerate(reversed(received), 1):
        print(f"  [{idx}] {' '.join(hop.split())}")
    urls: set[str] = set()
    for part in msg.walk():
        if part.get_content_type() in ("text/plain", "text/html"):
            body = part.get_content()
            if isinstance(body, str):
                urls.update(URL_RE.findall(body))
    print("\nDefanged URLs:")
    for u in sorted(urls):
        print(f"  {defang(u)}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <sample.eml>")
    analyze_eml(Path(sys.argv[1]))
