#!/usr/bin/env python3
import sys
from pathlib import Path

def parse_global_sshd(text: str) -> dict[str, str]:
    cfg: dict[str, str] = {}
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        parts = line.replace("=", " ", 1).split(None, 1)
        if len(parts) < 2:
            continue
        key, val = parts[0].lower(), parts[1].strip().lower()
        if key == "match":
            break
        cfg.setdefault(key, val)
    return cfg

def audit_sshd(path: Path) -> int:
    cfg = parse_global_sshd(path.read_text(encoding="utf-8"))
    issues: list[str] = []
    if cfg.get("permitrootlogin") != "no":
        issues.append(f"PermitRootLogin is '{cfg.get('permitrootlogin', '<unset>')}' (expected 'no')")
    if cfg.get("passwordauthentication") != "no":
        issues.append(f"PasswordAuthentication is '{cfg.get('passwordauthentication', '<unset>')}' (expected 'no')")
    tries = cfg.get("maxauthtries")
    if tries is None or not tries.isdigit() or int(tries) > 4:
        issues.append(f"MaxAuthTries is '{tries or '<unset>'}' (expected <= 4)")
    for msg in issues:
        print(f"FAIL: {msg}")
    if not issues:
        print("PASS: sshd_config meets baseline checks")
    return len(issues)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <sshd_config>")
    sys.exit(1 if audit_sshd(Path(sys.argv[1])) else 0)
```

