```python
#!/usr/bin/env python3
import json
import statistics
import sys
from collections import defaultdict
from pathlib import Path

def detect_beacons(path: Path, min_hits: int = 10, max_cv: float = 0.15) -> None:
    flows: dict[tuple[str, str, int], list[float]] = defaultdict(list)
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            if not line.strip():
                continue
            r = json.loads(line)
            key = (str(r["id.orig_h"]), str(r["id.resp_h"]), int(r["id.resp_p"]))
            flows[key].append(float(r["ts"]))
    for (src, dst, dport), times in flows.items():
        if len(times) < min_hits:
            continue
        times.sort()
        deltas = [times[i + 1] - times[i] for i in range(len(times) - 1) if times[i + 1] > times[i]]
        if len(deltas) < min_hits - 1:
            continue
        mean_dt = statistics.fmean(deltas)
        if mean_dt <= 0:
            continue
        cv = statistics.pstdev(deltas) / mean_dt
        if cv <= max_cv:
            print(f"{src} -> {dst}:{dport} count={len(times)} mean_dt={mean_dt:.2f}s cv={cv:.4f}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <conn.ndjson>")
    detect_beacons(Path(sys.argv[1]))
```

