        if delta <= 0:
            alerts.append(f"ALERT: non-incrementing FCntUp {fcnt_up} for {dev_eui}")
        elif delta > max_gap:
            alerts.append(f"ALERT: excessive FCntUp jump (+{delta}) for {dev_eui}")
