import sys
from pathlib import Path

def print_lineage(log_path: Path, target_pid: int) -> None:
    procs: dict[int, dict] = {}
    with log_path.open("r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                rec = json.loads(line)
                procs[int(rec["pid"])] = rec
