#!/usr/bin/env python3
import ast

def eval_condition(expr: str, bindings: dict[str, bool]) -> bool:
    tree = ast.parse(expr, mode="eval")

    def _walk(node: ast.AST) -> bool:
        if isinstance(node, ast.Expression):
            return _walk(node.body)
        if isinstance(node, ast.Name):
            if node.id not in bindings:
                raise KeyError(f"Unknown selector: {node.id}")
            return bool(bindings[node.id])
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            return not _walk(node.operand)
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                return all(_walk(v) for v in node.values)
            if isinstance(node.op, ast.Or):
                return any(_walk(v) for v in node.values)
        raise ValueError(f"Disallowed syntax node: {type(node).__name__}")

    return _walk(tree)

if __name__ == "__main__":
