#!/usr/bin/env python3
import sys
from pathlib import Path

def load_sysctl(root: Path) -> dict[str, str]:
    files = sorted((root / "etc" / "sysctl.d").glob("*.conf")) if (root / "etc" / "sysctl.d").is_dir() else []
    main_cfg = root / "etc" / "sysctl.conf"
