#!/usr/bin/env python3
import json
import math
import sys
from collections import defaultdict
from pathlib import Path

EARTH_KM = 6371.0

def haversine_km(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dp = math.radians(lat2 - lat1)
    dl = math.radians(lon2 - lon1)
    a = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * EARTH_KM * math.asin(math.sqrt(a))

def detect_impossible_travel(path: Path) -> None:
    by_user: dict[str, list[dict]] = defaultdict(list)
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                ev = json.loads(line)
                by_user[str(ev["user"])].append(ev)
    for user, events in by_user.items():
        events.sort(key=lambda e: float(e["ts_epoch"]))
        for a, b in zip(events, events[1:]):
            dist = haversine_km(float(a["lat"]), float(a["lon"]), float(b["lat"]), float(b["lon"]))
            hours = max((float(b["ts_epoch"]) - float(a["ts_epoch"])) / 3600.0, 1e-6)
            speed = dist / hours
