		fmt.Fprintf(os.Stderr, "Usage: %s <target_dir> <baseline.json>\n", os.Args[0])
		os.Exit(1)
	}
	root := os.Args[1]
	raw, err := os.ReadFile(os.Args[2])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	var base map[string]Entry
	if err := json.Unmarshal(raw, &base); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	seen := make(map[string]bool)
	_ = filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil || !d.Type().IsRegular() {
			return nil
		}
		rel, _ := filepath.Rel(root, p)
		seen[rel] = true
		info, err := d.Info()
		if err != nil {
			return nil
		}
		digest, err := fileHash(p)
		if err != nil {
			return nil
		}
		b, ok := base[rel]
		if !ok {
			fmt.Printf("ADDED    %s\n", rel)
		} else if b.SHA256 != digest {
			fmt.Printf("MODIFIED %s\n", rel)
		} else if b.Mode != uint32(info.Mode().Perm()) {
			fmt.Printf("CHMOD    %s\n", rel)
		}
		return nil
	})
	for rel := range base {
