```python
#!/usr/bin/env python3
import re
import sys
from pathlib import Path

RULE_RE = re.compile(r"rule\s+([A-Za-z_][A-Za-z0-9_]*)\s*\{(.*?)\n\}", re.DOTALL)
HEX_STR_RE = re.compile(r"\$[A-Za-z0-9_]*\s*=\s*\{([^}]+)\}")
HEX_TOK_RE = re.compile(r"^[0-9A-Fa-f?]{2}$")

def lint_yara(text: str) -> list[str]:
    errors: list[str] = []
    if text.count("{") != text.count("}"):
        errors.append("Unbalanced curly braces in file")
    for m in RULE_RE.finditer(text):
        name, body = m.group(1), m.group(2)
        for req in ("author", "description"):
            if not re.search(rf"\b{req}\s*=\s*\"[^\"]+\"", body):
                errors.append(f"{name}: missing meta key '{req}'")
        for hm in HEX_STR_RE.finditer(body):
            tokens = hm.group(1).split()
            for tok in tokens:
                if tok.startswith("[") and tok.endswith("]"):
                    continue
                if not HEX_TOK_RE.match(tok):
                    errors.append(f"{name}: invalid hex token '{tok}'")
    return errors

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <rules.yar>")
    errs = lint_yara(Path(sys.argv[1]).read_text(encoding="utf-8"))
    for e in errs:
        print(f"ERROR: {e}")
    sys.exit(1 if errs else 0)
