import struct
import sys
from pathlib import Path

PT_LOAD = 1
PF_X, PF_W = 0x1, 0x2

def static_elf_triage(path: Path) -> None:
    buf = path.read_bytes()
    if len(buf) < 64 or buf[:4] != b"\x7fELF" or buf[4] != 2:
        raise ValueError("Expected ELF64 binary")
    end = "<" if buf[5] == 1 else ">"
    (e_phoff,) = struct.unpack_from(f"{end}Q", buf, 32)
    e_phentsize, e_phnum, _shent, e_shnum = struct.unpack_from(f"{end}HHHH", buf, 54)
