            break
        p_type, p_flags, _poff, p_vaddr, _paddr, _fsz, p_memsz, _al = struct.unpack_from(f"{end}IIQQQQQQ", buf, off)
        if p_type == PT_LOAD and (p_flags & (PF_W | PF_X)) == (PF_W | PF_X):
            print(f"[FLAG] {path.name}: RWX PT_LOAD segment[{i}] vaddr=0x{p_vaddr:x} memsz=0x{p_memsz:x}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
