import heapq
import json
import sys
from pathlib import Path

def score_alert(ev: dict) -> int:
    tier = max(0, min(3, int(ev.get("asset_tier", 0))))
    pts = tier * 2
    if ev.get("is_admin"):
        pts += 2
    if ev.get("unsigned_binary"):
        pts += 3
    if ev.get("external_egress"):
