#!/usr/bin/env python3
import math
import sys
from collections import Counter
from pathlib import Path

def analyze_bytes(buf: bytes) -> dict[str, float]:
    n = len(buf)
    if n == 0:
        return {"entropy": 0.0, "ascii_ratio": 0.0, "chi2": 0.0}
    counts = Counter(buf)
    ent = -sum((c / n) * math.log2(c / n) for c in counts.values())
    printable = sum(cnt for b, cnt in counts.items() if 0x20 <= b <= 0x7E or b in (9, 10, 13))
    expected = n / 256.0
    chi2 = sum(((counts.get(b, 0) - expected) ** 2) / expected for b in range(256))
    return {"entropy": ent, "ascii_ratio": printable / n, "chi2": chi2}

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <file.bin>")
