```ts
import crypto from "node:crypto";
import { Request, Response, NextFunction } from "express";

export function verifyWebhook(secret: string) {
  return (req: Request & { rawBody?: Buffer }, res: Response, next: NextFunction) => {
    const ts = req.header("X-Pay-Timestamp") ?? "";
    const sig = req.header("X-Pay-Signature") ?? "";
    const now = Math.floor(Date.now() / 1000);
    if (!req.rawBody || !/^[0-9]+$/.test(ts) || Math.abs(now - Number(ts)) > 300) {
      return res.status(401).json({ error: "invalid timestamp" });
    }
    const payload = Buffer.concat([Buffer.from(`${ts}.`), req.rawBody]);
    const expected = crypto.createHmac("sha256", secret).update(payload).digest();
    const provided = Buffer.from(sig, "hex");
    if (expected.length !== provided.length || !crypto.timingSafeEqual(expected, provided)) {
      return res.status(401).json({ error: "invalid signature" });
    }
    next();
  };
}
