#!/usr/bin/env python3
import struct
import sys
from pathlib import Path

def rva_to_off(rva: int, sections: list[tuple[int, int, int, int]]) -> int | None:
    for va, vsz, rptr, rsz in sections:
        span = max(vsz, rsz)
        if va <= rva < va + span:
            return rva - va + rptr
    return None

def list_pe_dlls(path: Path) -> list[str]:
    buf = path.read_bytes()
    (pe_off,) = struct.unpack_from("<I", buf, 0x3C)
    if buf[:2] != b"MZ" or buf[pe_off : pe_off + 4] != b"PE\x00\x00":
        raise ValueError("Invalid PE header")
    _mach, nsec, _ts, _sym, _nsym, opt_sz, _ch = struct.unpack_from("<HHIIIHH", buf, pe_off + 4)
    opt_off = pe_off + 24
    (magic,) = struct.unpack_from("<H", buf, opt_off)
    imp_dd_off = opt_off + (104 if magic == 0x10B else 120 if magic == 0x20B else 0)
    if imp_dd_off == opt_off:
        raise ValueError("Unknown PE OptionalHeader magic")
    imp_rva, _imp_sz = struct.unpack_from("<II", buf, imp_dd_off)
    sec_base = opt_off + opt_sz
    secs = []
    for i in range(nsec):
        _nm, vsz, va, rsz, rptr, *_ = struct.unpack_from("<8sIIIIIIHHI", buf, sec_base + i * 40)
        secs.append((va, vsz, rptr, rsz))
    dlls: list[str] = []
    desc_off = rva_to_off(imp_rva, secs)
    while desc_off is not None and desc_off + 20 <= len(buf):
        oft, ts, fwd, name_rva, ft = struct.unpack_from("<IIIII", buf, desc_off)
        if (oft, ts, fwd, name_rva, ft) == (0, 0, 0, 0, 0):
            break
        noff = rva_to_off(name_rva, secs)
        if noff is not None and noff < len(buf):
            end = buf.find(b"\x00", noff)
            dlls.append(buf[noff : end if end != -1 else len(buf)].decode("ascii", errors="replace"))
        desc_off += 20
    return dlls

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <sample.exe>")
    for dll in list_pe_dlls(Path(sys.argv[1])):
        print(dll)
