    final_user: str | None = None
    saw_from = False
    for lineno, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split(None, 1)
        instr = parts[0].upper()
        rest = parts[1] if len(parts) > 1 else ""
        if instr == "FROM":
            saw_from = True
            final_user = None
            img = rest.split()[0]
            if img.lower() != "scratch" and "@sha256:" not in img:
                issues.append(f"line {lineno}: unpinned base image '{img}'")
        elif instr == "ADD" and re.search(r"https?://", rest, re.IGNORECASE):
            issues.append(f"line {lineno}: remote URL in ADD '{rest}'")
        elif instr == "ENV" and SECRET_RE.search(rest):
            issues.append(f"line {lineno}: secret-like ENV variable in '{rest}'")
        elif instr == "USER":
            final_user = rest.strip()
    if saw_from and (final_user is None or final_user in ("root", "0") or final_user.startswith("0:")):
        issues.append(f"final stage runs as root (USER={final_user!r})")
    return issues

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <Dockerfile>")
    errs = lint_dockerfile(Path(sys.argv[1]).read_text(encoding="utf-8"))
    for e in errs:
        print(f"WARN: {e}")
    sys.exit(1 if errs else 0)
```

