```python
#!/usr/bin/env python3
import re
import sys
from pathlib import Path

SID_RE = re.compile(r"\bsid\s*:\s*(\d+)\s*;")
REV_RE = re.compile(r"\brev\s*:\s*(\d+)\s*;")
MSG_RE = re.compile(r'\bmsg\s*:\s*"([^"]+)"\s*;')

def lint_suricata_rules(text: str) -> list[str]:
    errors: list[str] = []
    seen_sids: set[int] = set()
    for lineno, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        sm, rm, mm = SID_RE.search(line), REV_RE.search(line), MSG_RE.search(line)
        if not mm:
            errors.append(f"line {lineno}: missing non-empty msg option")
        if not rm or int(rm.group(1)) < 1:
            errors.append(f"line {lineno}: missing or invalid rev >= 1")
        if not sm:
            errors.append(f"line {lineno}: missing sid option")
            continue
        sid = int(sm.group(1))
        if sid < 1_000_000:
            errors.append(f"line {lineno}: local rule sid={sid} must be >= 1000000")
        if sid in seen_sids:
            errors.append(f"line {lineno}: duplicate sid={sid}")
        seen_sids.add(sid)
    return errors

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <local.rules>")
    errs = lint_suricata_rules(Path(sys.argv[1]).read_text(encoding="utf-8"))
    for e in errs:
        print(f"ERROR: {e}")
    sys.exit(1 if errs else 0)
```

