```python
#!/usr/bin/env python3
import re
import sys
from collections import Counter
from pathlib import Path

NAME_RE = re.compile(rb"/([A-Za-z0-9#._+-]+)")
HEX_ESC_RE = re.compile(rb"#([0-9A-Fa-f]{2})")
WATCH = {"/JS", "/JavaScript", "/OpenAction", "/AA", "/Launch", "/ObjStm"}

def unescape_pdf_name(raw_name: bytes) -> str:
    decoded = HEX_ESC_RE.sub(lambda m: bytes([int(m.group(1), 16)]), raw_name)
    return "/" + decoded.decode("latin1")

def scan_pdf_names(path: Path) -> Counter[str]:
    buf = path.read_bytes()
    if not buf.lstrip().startswith(b"%PDF-"):
        raise ValueError("Missing %PDF- header")
    counts: Counter[str] = Counter()
    for m in NAME_RE.finditer(buf):
        norm = unescape_pdf_name(m.group(1))
        if norm in WATCH:
            counts[norm] += 1
    return counts

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <sample.pdf>")
    res = scan_pdf_names(Path(sys.argv[1]))
    for k in sorted(WATCH):
        print(f"{k:<14}: {res[k]}")
