#!/usr/bin/env python3
import re
import sys
from pathlib import Path

USES_RE = re.compile(r"^\s*-?\s*uses\s*:\s*['\"]?([^'\"#\s]+)")
SHA40_RE = re.compile(r"^[0-9a-f]{40}$")
WRITE_ALL_RE = re.compile(r"^\s*permissions\s*:\s*write-all\b", re.IGNORECASE)

def lint_workflow(path: Path) -> list[str]:
    issues: list[str] = []
    for lineno, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        if WRITE_ALL_RE.search(raw):
            issues.append(f"{path}:{lineno}: overly broad 'permissions: write-all'")
        m = USES_RE.match(raw)
        if not m:
            continue
        ref = m.group(1)
        if ref.startswith(("./", "docker://")):
            continue
        if "@" not in ref or not SHA40_RE.match(ref.rsplit("@", 1)[1]):
            issues.append(f"{path}:{lineno}: unpinned external action '{ref}'")
    return issues

if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(f"Usage: {sys.argv[0]} <workflow1.yml> [workflow2.yml ...]")
    all_issues = [msg for arg in sys.argv[1:] for msg in lint_workflow(Path(arg))]
    for msg in all_issues:
        print(f"WARN: {msg}")
    sys.exit(1 if all_issues else 0)
