#!/usr/bin/env python3
import json
import re
import sys
from collections import defaultdict
from pathlib import Path

HEX_RE = re.compile(r"[0-9a-fA-F]{6,}")
NUM_RE = re.compile(r"\d+")

def mask_socket_path(p: str) -> str:
    s = HEX_RE.sub("<HEX>", p.strip())
