            tpl = mask_socket_path(sp)
            host = str(ev["host"])
            tpl_hosts[tpl].add(host)
            tpl_sample.setdefault(tpl, ( str(ev.get("proc", "")), sp ))
    for tpl, hosts in sorted(tpl_hosts.items()):
        if len(hosts) == 1:
            proc, raw_sp = tpl_sample[tpl]
            print(f"host={next(iter(hosts))} proc={proc} template={tpl} sample={raw_sp}")

if __name__ == "__main__":
