#!/usr/bin/env python3
import json
import statistics
import sys
from pathlib import Path

def detect_mad_outliers(path: Path, thresh: float = 5.0) -> None:
    sizes: list[int] = []
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                sizes.append(int(json.loads(line).get("resp_bytes", 0)))
    if len(sizes) < 10:
        return
    med = statistics.median(sizes)
    mad = statistics.median([abs(x - med) for x in sizes])
    if mad == 0:
        return
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            if not line.strip():
                continue
            ev = json.loads(line)
            val = int(ev.get("resp_bytes", 0))
            mod_z = 0.6745 * (val - med) / mad
            if mod_z >= thresh:
                print(f"mod_z={mod_z:.2f} bytes={val} src={ev.get('src_ip')} url={ev.get('url')}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <proxy.ndjson>")
    detect_mad_outliers(Path(sys.argv[1]))
