REDIRECT_KEYS = ("url", "u", "redirect", "target", "dest", "next")

def defang(u: str) -> str:
    return u.replace("https://", "hxxps://").replace("http://", "hxxp://").replace(".", "[.]")

def unwrap_url(raw_url: str, max_depth: int = 5) -> list[str]:
    chain = [raw_url.strip()]
